import { functionalUpdate, getPaginationRowModel } from '@tanstack/react-table';
import React, { ReactElement, ReactNode } from 'react';
import { isElement } from 'react-is';

import { _useControllableState } from '../../../../core/hooks/useControllableState.js';
import type { TableOptions } from '../../hooks/useTable/types.js';
import type { DataTableV2Props } from '../../public.api.js';

/**
 * DataTableV2.Pagination props.
 * @public
 */
export type DataTableV2PaginationProps = {
  /**
   * The element's unique identifier. See [MDN](https://developer.mozilla.org/en-US/docs/Web/HTML/Global_attributes/id).
   */
  id?: string;
  /**
   * Test id used for matching the pagination container.
   */
  'data-testid'?: string;
} & ( // Uncontrolled pageIndex options
  | {
      /**
       * Initial page index in an uncontrolled scenario.
       * @defaultValue 0
       */
      defaultPageIndex?: number;
      /** Current page index in a controlled scenario. */
      pageIndex?: never;
      /** Called when the page index changes. Provides the changed page index along with the underlying trigger. */
      onPageIndexChange?: (
        pageIndex: number,
        trigger?: 'user' | 'internal',
      ) => void;
    }
  // Controlled pageIndex options
  | {
      /**
       * Initial page index in an uncontrolled scenario.
       * @defaultValue 0
       */
      defaultPageIndex?: never;
      /** Current page index in a controlled scenario. */
      pageIndex: number;
      /** Called when the page index changes. Provides the changed page index along with the underlying trigger. */
      onPageIndexChange: (
        pageIndex: number,
        trigger?: 'user' | 'internal',
      ) => void;
    }
) &
  // uncontrolled PageSize
  (| {
        /**
         * Default number of rows per page (uncontrolled).
         * @defaultValue 10
         */
        defaultPageSize?: number;
        /** Number of rows per page (controlled) */
        pageSize?: never;
        /** Handler that is called when the page size changes. */
        onPageSizeChange?: (pageSize: number) => void;
      }
    // Controlled PageSize
    | {
        /**
         * Default number of rows per page (uncontrolled).
         * @defaultValue 10
         */
        defaultPageSize?: never;
        /** Number of rows per page (controlled) */
        pageSize: number;
        /** Handler that is called when the page size changes. */
        onPageSizeChange: (pageSize: number) => void;
      }
  ) &
  // Client side pagination
  (| {
        /** Whether the previous page is available (if not, the go to previous page button should be disabled).	*/
        enablePreviousPage?: never;
        /** Whether the next page is available (if not, the go to next page button should be disabled). */
        enableNextPage?: never;
      }
    // Server side pagination
    | {
        /** Whether the previous page is available (if not, the go to previous page button should be disabled).	*/
        enablePreviousPage: boolean;
        /** Whether the next page is available (if not, the go to next page button should be disabled). */
        enableNextPage: boolean;
      }
  );

/**
 * DataTableV2 slot definition.
 * @public
 */
export function DataTableV2Pagination(props: DataTableV2PaginationProps) {
  return null;
}

/**
 * Helper function that will check if a passed component is of type `DataTableV2Pagination`
 * @internal
 */
export function _isDataTableV2Pagination(
  child: ReactNode,
): child is ReactElement<DataTableV2PaginationProps> {
  if (isElement(child) && child.type === DataTableV2Pagination) {
    return true;
  }
  return false;
}

//#region React table extension interfaces
export interface DataTableV2PaginationOptions {
  enablePagination?: boolean;

  availablePaginationOptions?: number[];
}

export interface DataTableV2PaginationInitialTableState {
  pagination: {
    pageIndex: number;
    pageSize: number;
    enableNextPage?: boolean;
    enablePreviousPage?: boolean;
  };
}
export interface DataTableV2PaginationTableState {
  pagination: {
    pageIndex: number;
    pageSize: number;
    enableNextPage?: boolean;
    enablePreviousPage?: boolean;
  };
}

//#endregion

const DATATABLEV2_PAGINATION_DEFAULTS = {
  pageSize: 10,
  pageIndex: 0,
  pageSizeOptions: [10, 20, 30, 40, 50],
};

/**
 * Helper function that clamps the provided page size to a value
 * within the provided options array by looking at low and high boundaries,
 * and if necessary round to the closest valid option.
 */
function _clampPageSize(pageSize: number, pageSizeOptions: number[]): number {
  if (pageSizeOptions.includes(pageSize)) {
    return pageSize;
  }

  const lowOption = pageSizeOptions.at(0);
  const highOption = pageSizeOptions.at(-1);

  if (lowOption && pageSize < lowOption) {
    return lowOption;
  }

  if (highOption && pageSize > highOption) {
    return highOption;
  }

  const insertIndex = pageSizeOptions.findIndex((value, index, options) => {
    return (
      (pageSize > value && pageSize < options[index + 1]) ??
      Number.MAX_SAFE_INTEGER
    );
  });
  const lowBound = pageSizeOptions.at(insertIndex);
  const highBound = pageSizeOptions.at(insertIndex + 1);
  if (lowBound && highBound) {
    // Pick the closer of the two options.
    if (pageSize - lowBound >= highBound - pageSize) {
      return highBound;
    } else {
      return lowBound;
    }
  }

  // This option should never happen, all possible scenarios are covered in the other statements
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
  return lowOption!;
}

/** Configuration hook for pagination of the DataTableV2. */
export function usePagination<TData>(
  props: DataTableV2Props<TData>,
  options: TableOptions<TData>,
) {
  const paginationElement = React.Children.toArray(props.children).find(
    _isDataTableV2Pagination,
  );

  // Clamp the controlled and uncontrolled values of the pageSize
  // to available values.
  const clampedPageSize =
    paginationElement?.props.pageSize !== undefined
      ? _clampPageSize(
          paginationElement?.props.pageSize,
          DATATABLEV2_PAGINATION_DEFAULTS.pageSizeOptions,
        )
      : undefined;
  const clampedDefaultPageSize =
    paginationElement?.props.defaultPageSize !== undefined
      ? _clampPageSize(
          paginationElement?.props.defaultPageSize,
          DATATABLEV2_PAGINATION_DEFAULTS.pageSizeOptions,
        )
      : undefined;

  const [pageSize, setPageSize] = _useControllableState({
    value: clampedPageSize,
    defaultValue: clampedDefaultPageSize,
    onChange: paginationElement?.props.onPageSizeChange,
  });

  const [pageIndex, setPageIndex] = _useControllableState({
    value: paginationElement?.props.pageIndex,
    defaultValue: paginationElement?.props.defaultPageIndex,
    onChange: paginationElement?.props.onPageIndexChange,
  });

  // Init the paginationOptions to make sure they are a valid boolean.
  options.enablePagination = false;

  if (paginationElement) {
    options.enablePagination = true;
    options.availablePaginationOptions =
      DATATABLEV2_PAGINATION_DEFAULTS.pageSizeOptions;
    // Server side pagination.
    if (
      paginationElement.props.enableNextPage !== undefined &&
      paginationElement.props.enablePreviousPage !== undefined
    ) {
      options.manualPagination = true;
      // Ensure pageCount is considered unknown to react table.
      options.pageCount = -1;
    } else {
      options.manualPagination = false;
      options.getPaginationRowModel = getPaginationRowModel();
    }

    options.state = {
      ...options.state,
      pagination: {
        pageSize: pageSize ?? DATATABLEV2_PAGINATION_DEFAULTS.pageSize,
        pageIndex: pageIndex ?? DATATABLEV2_PAGINATION_DEFAULTS.pageIndex,
        enablePreviousPage: paginationElement.props.enablePreviousPage,
        enableNextPage: paginationElement.props.enableNextPage,
      },
    };

    options.onPaginationChange = (updater) => {
      const nextState = functionalUpdate(updater, options.state?.pagination);
      if (
        nextState?.pageIndex !== pageIndex &&
        nextState?.pageIndex !== undefined
      ) {
        setPageIndex(nextState.pageIndex);
      }
      if (
        nextState?.pageSize !== pageSize &&
        nextState?.pageSize !== undefined
      ) {
        setPageSize(nextState.pageSize);
      }
    };
  }

  return null;
}
